quit tSC

    try {

     // sample input data

	//s pRequest.attrName = "uidNumber" $lb(0,"uidNumber",$lb(58129))
	//s pRequest.attrVal = 58129


        // prepare search parameters
        ;set Filter=pRequest.Filter

        // add or update
        set pResponse = ##class(Ens.StringRequest).%New()
        Set tSC=..Adapter.AddModifyExts(pRequest.filter,pRequest.baseDN,pRequest.attrName,pRequest.attrVal,pRequest.action)
        if $$$ISERR(tSC) {
            set pResponse.StringValue=$system.Status.GetErrorText(tSC)
            quit
        }



    }
    catch Err {
        set tSC=Err.AsStatus()

        set pResponse.StringValue=$system.Status.GetErrorText(tSC)
    }
    Quit tSC

